document.addEventListener('DOMContentLoaded', function () {
  if (window.innerWidth > 1024) return;

  const toc = document.querySelector('.case-content-table .elementor-toc__body');
  const listItems = toc?.querySelectorAll('.elementor-toc__list-item-text');

  if (!toc || listItems.length === 0) return;

  // Cria o select
  const select = document.createElement('select');
  select.className = 'mobile-toc-select';
  select.style.marginBottom = '20px';

  // Option padrão
  const defaultOption = document.createElement('option');
  defaultOption.textContent = 'Ir para seção';
  defaultOption.disabled = true;
  defaultOption.selected = true;
  select.appendChild(defaultOption);

  // Preenche com as âncoras
  listItems.forEach((item) => {
    const option = document.createElement('option');
    option.textContent = item.textContent;
    option.value = item.getAttribute('href');
    select.appendChild(option);
  });

  // Substitui a lista pelo select
  toc.innerHTML = '';
  toc.appendChild(select);

  // Ao mudar, scroll para a âncora
  select.addEventListener('change', function () {
    const targetId = this.value;
    const target = document.querySelector(targetId);
    if (target) {
      const offset = 100; // ajuste se tiver header fixo
      const top = target.getBoundingClientRect().top + window.scrollY - offset;
      window.scrollTo({ top, behavior: 'smooth' });
    }
  });
});

document.addEventListener('DOMContentLoaded', function () {
  const select = document.querySelector('.mobile-toc-select');
  const headerTitle = document.querySelector('.elementor-toc__header-title');

  if (!select || !headerTitle) return;

  // Quando abre o select (foco)
  select.addEventListener('focus', () => {
    headerTitle.style.fontWeight = '700 !important';
  });

  // Quando fecha (perde foco)
  select.addEventListener('blur', () => {
    headerTitle.style.fontWeight = '400  !important';
  });
});
